import { test, mock } from "node:test";
import assert from "node:assert/strict";
import { FakeClock } from "../src/clock/fakeClock.js";
import { createHoldService } from "../src/ticketing/holds.js";
import { scheduleReminders } from "../src/ticketing/reminders.js";

const MIN = 60_000;

function setup() {
    const clock = new FakeClock(1_000_000);
    const notifier = { seatReleased: mock.fn() };
    const holds = createHoldService({ clock, notifier });
    return { clock, notifier, holds };
}

test("a held seat cannot be held by someone else", () => {
    const { holds } = setup();
    assert.equal(holds.hold("A1", "ana").ok, true);
    assert.deepEqual(holds.hold("A1", "ben"), { ok: false, reason: "held" });
});

test("advancing less than the TTL keeps the hold", () => {
    const { holds, clock, notifier } = setup();
    holds.hold("A1", "ana");
    clock.advance(9 * MIN);
    assert.equal(holds.isHeld("A1"), true);
    assert.equal(notifier.seatReleased.mock.callCount(), 0);
});

test("an expired hold is released and the buyer is told", () => {
    const { holds, clock, notifier } = setup();
    holds.hold("A1", "ana");
    clock.advance(10 * MIN);
    assert.equal(holds.isHeld("A1"), false);
    assert.equal(notifier.seatReleased.mock.callCount(), 1);
    assert.deepEqual(notifier.seatReleased.mock.calls[0].arguments, ["ana", "A1"]);
});

test("confirming a hold cancels its expiry timer", () => {
    const { holds, clock, notifier } = setup();
    holds.hold("A1", "ana");
    assert.equal(holds.confirm("A1", "ana"), true);
    assert.equal(clock.pending(), 0);
    clock.advance(30 * MIN);
    assert.equal(notifier.seatReleased.mock.callCount(), 0);
});

test("holds expire in deadline order and are stamped with their own deadline", () => {
    const { holds, clock } = setup();
    const start = clock.now();
    holds.hold("B1", "ben", 8 * MIN);
    holds.hold("B2", "cy", 2 * MIN);
    holds.hold("B3", "di", 5 * MIN);
    clock.advance(10 * MIN);
    const log = holds.releaseLog();
    console.log("release log:", log.map((r) => `${r.seatId}@+${(r.at - start) / MIN}min`).join(", "));
    assert.deepEqual(log.map((r) => r.seatId), ["B2", "B3", "B1"], "earliest deadline must fire first");
    assert.deepEqual(log.map((r) => r.at - start), [2 * MIN, 5 * MIN, 8 * MIN], "now() inside a callback is its own deadline");
});

test("reminders keep firing at their interval within a single advance", () => {
    const clock = new FakeClock(0);
    const send = mock.fn();
    scheduleReminders({ clock, send, firstAfterMs: 5 * MIN, everyMs: 2 * MIN, maxReminders: 3 });
    clock.advance(10 * MIN);
    assert.deepEqual(send.mock.calls.map((c) => c.arguments[0].at), [5 * MIN, 7 * MIN, 9 * MIN]);
});

test("cancelled reminders never fire", () => {
    const clock = new FakeClock(0);
    const send = mock.fn();
    const r = scheduleReminders({ clock, send, firstAfterMs: 5 * MIN, everyMs: 2 * MIN, maxReminders: 3 });
    r.cancel();
    clock.advance(20 * MIN);
    assert.equal(send.mock.callCount(), 0);
});
